import{_ as a,c as o,o as t,ah as r}from"./chunks/framework.Bx_Cr0v5.js";const c=JSON.parse('{"title":"Map approval process","description":"","frontmatter":{},"headers":[],"relativePath":"mapping/approval.md","filePath":"mapping/approval.md"}'),s={name:"mapping/approval.md"};function i(l,e,n,p,d,m){return t(),o("div",null,e[0]||(e[0]=[r('<h1 id="map-approval-process" tabindex="-1">Map approval process <a class="header-anchor" href="#map-approval-process" aria-label="Permalink to &quot;Map approval process&quot;">​</a></h1><p>The map approval process structure will closely resemble GOKZ with a few key details still to be finalized. The current process to get your map approved for the global map pool is detailed below.</p><h2 id="_1-submission" tabindex="-1">1. Submission <a class="header-anchor" href="#_1-submission" aria-label="Permalink to &quot;1. Submission&quot;">​</a></h2><ul><li>Upload your map to the <a href="https://steamcommunity.com/app/730/workshop" target="_blank" rel="noreferrer">CS2 Steam Workshop</a>.</li><li>Post your map in the <strong>new-maps</strong> channel on the <a href="https://discord.gg/R593VhE" target="_blank" rel="noreferrer">Kreedz Mapping Discord server</a> for testing.</li><li>After sufficient testing and adjustments have taken place, post your map to the <strong>cs2-global-map-submission</strong> channel on the <a href="https://discord.gg/R593VhE" target="_blank" rel="noreferrer">Kreedz Mapping Discord server</a>.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li>Maps which have not been posted to <strong>new-maps</strong> for testing will be instantly denied. If you do not receive feedback in <strong>new-maps</strong> after two weeks, you may submit your map. However, any issues found during review may lead to your map being denied.</li><li>A workshop link, descriptions of your course names and further details are required to be included with your submission. When posting your submission check the submission post guidelines beforehand to ensure your post meets every criteria.</li></ul></div><h2 id="_2-review" tabindex="-1">2. Review <a class="header-anchor" href="#_2-review" aria-label="Permalink to &quot;2. Review&quot;">​</a></h2><ul><li><strong>The global map approval team</strong>, a group of experienced KZ community members will review the map. They are responsible for evaluating the difficulty, ranking potential and adherence to community standards for each course.</li><li>Maps will be assessed on objective metrics such as design, lighting, gameplay and difficulty.</li><li>The team will also consider whether the course is &quot;reasonable to compete on&quot; allowing for some flexibility and creative expression in map design.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li>Each map approval team member will provide their own review for submitted maps. Sometimes one member may deny a map despite a majority voting for approval. In such circumstances the reasoning for denial is thoroughly reviewed and approval is determined by the map approval team leader.</li></ul></div><h2 id="_3-denied-maps" tabindex="-1">3. Denied maps <a class="header-anchor" href="#_3-denied-maps" aria-label="Permalink to &quot;3. Denied maps&quot;">​</a></h2><ul><li>During a <strong>map release</strong>, maps submitted which have not met the standard expected for the global map pool will be denied.</li><li>If your map is denied, you are encouraged to resolve any issues determined by the map approval team, post your updates to <strong>new-maps</strong> for testing, and resubmit for the next map release.</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p></p><ul><li>Given that CS2KZ is still undergoing development, the standards and guidelines for global maps are subject to occasional amendments.</li></ul></div><h2 id="_4-approved-maps" tabindex="-1">4. Approved maps <a class="header-anchor" href="#_4-approved-maps" aria-label="Permalink to &quot;4. Approved maps&quot;">​</a></h2><ul><li>During a <strong>map release</strong>, approved maps will be added to the global CS2KZ map pool and made available for players to compete on in ranked or unranked settings (subject to the filter for each course).</li></ul>',13)]))}const h=a(s,[["render",i]]);export{c as __pageData,h as default};
